-- Disposable local DB only; production migrations + engine required, no rpc-fixtures preload.
\set ON_ERROR_STOP on
begin;
create temp table utility_result(id text primary key);
grant all on utility_result to authenticated;
create function pg_temp.utility_check(k text, ok boolean) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'UTILITY_MISMATCH: %',k;end if;insert into utility_result values(k);end$$;
create function pg_temp.utility_error(k text,q text,st text,msg text) returns void language plpgsql as $$declare e text;s text;begin begin execute q; exception when others then e:=sqlerrm;s:=sqlstate;end;if e is distinct from msg or s is distinct from st then raise exception 'UTILITY_ERROR_MISMATCH: % state=% msg=%',k,s,e;end if;insert into utility_result values(k);end$$;
